import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Visual Agentic Memory: Enabling Online Long Video Understanding via Online Indexing, Hierarchical Memory, and Agentic Retrieval","description":"","frontmatter":{"title":"Visual Agentic Memory: Enabling Online Long Video Understanding via Online Indexing, Hierarchical Memory, and Agentic Retrieval","arxiv":"2605.16481","date":"2026-05-15","authors":"Aiden Yiliu Li, Nels Numan, Anthony Steed","categories":"cs.AI, cs.CV","topics":"长视频理解, 视觉记忆, 智能体检索","outline":[2,2]},"headers":[],"relativePath":"papers/2605.16481.md","filePath":"papers/2605.16481.md","lastUpdated":null}'),l={name:"papers/2605.16481.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="visual-agentic-memory-enabling-online-long-video-understanding-via-online-indexing-hierarchical-memory-and-agentic-retrieval" tabindex="-1">Visual Agentic Memory: Enabling Online Long Video Understanding via Online Indexing, Hierarchical Memory, and Agentic Retrieval <a class="header-anchor" href="#visual-agentic-memory-enabling-online-long-video-understanding-via-online-indexing-hierarchical-memory-and-agentic-retrieval" aria-label="Permalink to &quot;Visual Agentic Memory: Enabling Online Long Video Understanding via Online Indexing, Hierarchical Memory, and Agentic Retrieval&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.16481" target="_blank" rel="noreferrer">2605.16481</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-15</td></tr><tr><td><strong>作者</strong></td><td>Aiden Yiliu Li, Nels Numan, Anthony Steed</td></tr><tr><td><strong>分类</strong></td><td>cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>免训练地把视频流在线切成 moment 与 event 两级记忆，用 Otsu 自适应阈值决定何时提交边界，把原始帧当作一等证据保留下来，查询时由 MLLM 做 search / inspect / summarize / answer 的有界多轮检索并给出可回溯的引用。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/long-video-understanding">长视频理解</a></p></blockquote><p>本页依据 <code>arxiv.org/e-print/2605.16481</code> 取回的 LaTeX 源码撰写（正文、附录与全部表格）。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>高带宽视频采集已经很便宜，把无界的流变成一份稳定、可查询、可核验的记忆底座却仍然很难。作者把长视频理解拆成三个耦合的要求：在线索引（在流式约束下保留跨时间跨空间的视觉证据）、层次记忆（让时间线上下文与可恢复的原始观测保持对齐，而不是只留压缩后的摘要）、智能体检索（在这份记忆上做任务相关的搜索与视觉核验）。</p><p>这个拆法针对的是一个具体的失败模式，作者称之为 <strong>recoverability collapse</strong>：压缩式记忆保住了语义要旨，却把后续验证所需的视觉证据丢了。一旦细粒度细节被丢弃，后面的推理就没法回头对照原始观测，引用保真度和回溯检查都失效。递归式智能体还会累积 memory drift——中间推理无法对照被保留的观测来检查。</p><p>这件事的紧迫性由 MM-Lifelong 的月级切分给出：105.6 小时、跨 51 天的连续素材，人类与模型的差距超过 70 个百分点（82.5% 对不超过 17.62%）。这个数字说明终身记忆基本还是空白。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>作者把现有系统归成三类范式。</p><p><strong>直接生成式推理</strong>（Video-ChatGPT 一类）从上下文里的视觉 token 直接解码答案，通常配定速采样或有界上下文提示。时长一长上下文就饱和，注意力被稀释。ViSpeak 和 StreamAgent 这类流式改良强化了实时交互与任务预判，但没有做到持久的、保留证据的架构。</p><p><strong>压缩式记忆建模</strong>是第二类：MovieChat(+) 的稀疏保留与摘要、StreamForest 的渐进压缩层次、Infinity-Video 的连续时间整合、FluxMem 用 Otsu 阈值做时空冗余去除、StreamMind 的在线记忆压缩。它们用证据保真度换有界存储，一旦细节被丢，后续推理无法重访原始观测。</p><p><strong>智能体式推理</strong>是第三类：EGAgent 的图结构语义记忆、LVAgent 的多智能体协作、VideoExplorer 训练出的&quot;用视频思考&quot;策略、EventMemAgent 的层次事件记忆、VideoARM 的动态层次记忆、WorldMM 的多模态记忆、TeleMem、LifelongMemory、以及 ReMA 的递归信念更新。作者的批评很具体：<strong>用工具不等于保留证据</strong>。多数智能体没有把原始 RGB 观测当成一等的可查询底座，因此在可搜索池变大时会出现全局定位坍塌；递归变体还对早期假设错误敏感，错误被继承而不是通过直接查证被纠正。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是把问题从&quot;上下文多长&quot;挪到&quot;记忆怎么组织&quot;。既然压缩必然损失可恢复性，那就干脆不压缩关键证据本身，而是压缩<strong>索引密度</strong>：把大量近乎静止的帧丢掉，把发生变化的那一帧留成完整证据。</p><p>第二步是怎么判断&quot;发生了变化&quot;。固定相似度阈值不行，因为 embedding 的变化幅度依赖场景动态、相机运动和环境稳定性。作者维护一段滑动的距离历史 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0097em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0097em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，在样本足够时用 Otsu 分割自动求阈值。这一步与 FluxMem 用 Otsu 做 token 削减在方法上很近，区别在于这里用它做<strong>保留证据的索引</strong>而不是做压缩。</p><p>第三步是承认单一表示不够。精确的帧级匹配和抽象的事件级回忆在不同条件下各自失效，于是把 moment 聚成 event，让事件摘要负责粗检索、原始帧负责细核验，两条通路共享元数据以免对齐损失。</p><p>第四步是查询时怎么用。既然记忆里同时有摘要和原始帧，检索就不该是一次性的 top-k，而应是一个 observe–hypothesise–inspect 的有界循环，把动作限制在可解释的原语上以保持可审计性。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>长时程理解需要的不是更长的上下文，而是一份<strong>可以回头看</strong>的底座：把变化点留成原始帧，把连续段落聚成带摘要的事件，然后让模型像人查资料一样先粗搜再逐条核验、最后给出指向具体证据的引用。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>Stage 1 帧过滤</strong>。先做两道便宜的图像级门。清晰度用 Laplacian 方差 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">Sharpness</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1002em;vertical-align:-0.2861em;"></span><span class="mord text"><span class="mord">Var</span></span><span class="mopen">(</span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathrm mtight" style="margin-right:0.0139em;">gray</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，低于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">20.0</span></span></span></span> 丢弃；再做嵌入前的冗余抑制，默认 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">20.0</span></span></span></span>（灰度平均绝对差）、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ss</span><span class="mord mathnormal mtight">im</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.92</span></span></span></span>（结构相似度）、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">hi</span><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0</span></span></span></span>（保持宽松）。两道门都过了才进入嵌入。</p><p><strong>Stage 2 嵌入</strong>。对保留帧提取稠密 embedding <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，作为面向检索的表示层；MLLM 只负责事件摘要、视觉核验与答案合成。</p><p><strong>Stage 3 边界保持的 moment 提交</strong>。计算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mop">cos</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0097em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0097em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 上的 Otsu 分割自适应给出（历史不足时回退到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight">im</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.88</span></span></span></span>）。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 的帧作为冗余上下文被缓冲；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 时把缓冲的端点提交为一个 moment，并把新帧设为新参考。同一套 Otsu 分析在 moment 距离序列上找局部峰、用放宽的阈值定 event 边界，并设最大事件时长 300 秒的上限。全程严格在线，不访问未来帧。</p><p><strong>层次记忆</strong>。按年龄 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span></span></span></span> 分三档：recent（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 小时）最小间隔 1.0 秒、不额外重压缩；mid（1–24 小时）最小间隔 20.0 秒、最长边 768 px、JPEG 质量 70；long（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">24</span></span></span></span> 小时）最小间隔 120.0 秒、最长边 512 px、质量 45。有几条保护规则：最早与最新的帧永远保留；长期档里与事件关联的帧不参与常规稀疏化；压缩在保留集合确定之后才施加，两套时间表逻辑分离。每个事件维护保留的 moment、embedding、由 MLLM 从同一段有界证据写出的摘要 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、以及元数据 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mclose">)</span></span></span></span>。</p><p><strong>智能体检索</strong>。有界多轮循环，动作空间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6891em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord text"><span class="mord texttt">search</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord texttt">inspect</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord texttt">summarize</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord texttt">answer</span></span><span class="mclose">}</span></span></span></span>。search 同时走两条通路：时间通路对事件摘要算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">E</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mop">cos</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf" style="margin-right:0.016em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，空间通路对帧 embedding 算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">V</span><span class="mord mathnormal mtight" style="margin-right:0.0785em;">I</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">cos</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。检索结果一律视为暂定，必须经 \\texttt{inspect} 直接看帧核验。答案必须绑定一个 \\texttt{best_ref}（形如 <code>(turn_idx, result_idx)</code> 的指针），缺失或非法时回退到最高分候选。回合预算耗尽或进展停滞则强制终止。</p><p><strong>工程约束</strong>。控制器输出用 Pydantic 严格模式解析（<code>extra=&quot;forbid&quot;</code>），<code>search.top_k</code> 限 1–200，<code>inspect.max_frames</code> 限 1–16，锚点窗口每侧不超过 7 天。首次 JSON 非法时追加一次修复指令重询，仍失败则回退到宽松 search 而不终止循环。</p><p><strong>模型配置</strong>。全部实验用 Gemini 3 Flash 作查询时 MLLM、Gemini Embedding 2 作索引与检索嵌入，通过 OpenRouter 与 Google Cloud API 访问，初始采样率 0.5 fps。运行时实例化三个 MLLM 角色：轻量 router（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0</span></span></span></span>，300 token）、主 planner（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1</span></span></span></span>，500 token）、多模态 inspector/generator（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1</span></span></span></span>，700 token）。</p><p><strong>一个具体例子</strong>。问&quot;上周三我把钥匙放哪了&quot;，planner 先 search 事件摘要通路找&quot;钥匙&quot;相关事件，拿到若干候选区间；然后 inspect 这些区间里保留的原始帧（每次至多 16 帧）确认哪一帧真的出现了放钥匙的动作；确认后 answer，并把 best_ref 指向那一帧所在的 turn 与 result 序号。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化集中在索引侧，且都很轻。变化检测用余弦距离 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mop">cos</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7692em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">AdaptiveThreshold</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathcal" style="margin-right:0.0097em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0097em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 由 Otsu 在最近距离直方图上做二分类给出。Otsu 的含义是找一个阈值把直方图分成两组、使组间方差最大；用在这里等价于假设&quot;冗余帧的距离&quot;和&quot;变化帧的距离&quot;构成双峰分布，让数据自己决定分界。这条假设在场景稳定时成立得很好，在持续缓慢变化的场景里会退化——因为此时直方图是单峰的，Otsu 仍会硬切出一个阈值。</p><p>事件形成写成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>，摘要为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">MLLM</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，检索侧的核验写成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2128em;vertical-align:-0.3013em;"></span><span class="mord text"><span class="mord">Inspector</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathcal" style="margin-right:0.1464em;">X</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8247em;"><span style="top:-2.4169em;margin-left:-0.1464em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">s</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.1464em;">X</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9115em;"><span style="top:-2.3987em;margin-left:-0.1464em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">m</span><span class="mord mathnormal mtight">p</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3013em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">Q</span><span class="mclose">)</span></span></span></span>。这些是记号而非推导；本文的贡献在系统结构而不在数学。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>第一个问题：在严格在线约束下表现如何。</strong> OVO-Bench 含 644 段视频、3,100 条查询，时长从几分钟到约半小时，要求每个回答只基于查询时刻之前可得的观测，并把在线能力拆成 Real-Time（RT）、Backward Tracing（BT）、Forward Active Responding（Fwd）三块。</p><p>表 <code>tab:ovobench</code> 的关键行：VAM 的 RT 均值 78.94、BT 均值 57.89、Fwd 均值 49.01、<strong>RT+BT 均值 68.41</strong>、Overall 61.95。同底座的端到端 Gemini 3 Flash 分别是 RT 72.44、BT 62.47、Fwd 57.15、RT+BT 67.46、Overall <strong>64.02</strong>。人类为 92.77 / 92.81。其他强基线：EventMemAgent RT+BT 63.16、Overall 60.75；ViSpeak 61.90 / 59.35；Streamo-7B 58.31 / 57.86；GPT-4o 62.61 / 59.54。</p><p>RT 的分项增益作者列了：ACR +7.34、ATR +2.59、STU +23.20、OJR +3.26。Fwd 一栏作者主动做了解释：VAM 的控制器是显式寻证且以引用为导向的，一旦检索到看起来足够的观测就倾向于作答，即使流还没揭示决定性的后续线索。</p><p><strong>第二个问题：能不能撑到月级。</strong> MM-Lifelong 的 train@month 切分含 266 道题，跨 105.6 小时 / 51 天。表 <code>tab:mmlifelong_trainmonth</code>：GPT-5 10.15 / Ref@300 1.39；Qwen3-VL-235B-A22B 9.09 / 0.39；Qwen3-VL-30B-A3B 8.33 / 0.48；Video-XL-2-8B 6.02 / 0.00；LongVT-7B 5.83 / 1.71；ReMA with GPT-5 <strong>17.62 / 9.91</strong>；ReMA with Qwen3VL-A22B 14.23 / 6.01；<strong>VAM 17.11 / 3.65</strong>；人类 82.5 / 31.2。Ref@300 是按 300 秒分辨率量化的时序定位（时间轴切成 5 分钟一格，预测线索区间按该粒度与标注区间对分）。作者对自己 Ref@300 偏低给了解释：VAM 按事件摘要粒度检索，单个事件可能跨越远超 300 秒线索窗的区间，而 Ref@300 测的是区间级 IoU，因此&quot;检索正确但边界粗&quot;会得低分。</p><p><strong>第三个问题：省了多少存储。</strong> 表 <code>tab:mmlifelong_cost</code>：原始帧 11,406,923（100%）；均匀 1 fps 380,304（3.33%，是 VAM 的 55.3 倍）；均匀 0.5 fps 190,152（1.67%，27.7 倍）；VAM 输出 6,876（<strong>0.06%</strong>）。作者强调这个缩减不是靠更低的名义采样率，而是靠边界敏感的过滤。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：长时程视频理解的核心矛盾是压缩带来的可恢复性坍塌，把原始帧当一等证据保留是一条与主流压缩路线相反的赌注。VAM 用两道便宜的图像级门加 Otsu 自适应的嵌入距离阈值做在线索引，在 MM-Lifelong 月级流上只留下 0.06% 的帧（6,876 帧对 1,140 万帧）。OVO-Bench 上 RT+BT 均值 68.41 略高于同底座端到端的 67.46，但 Overall 61.95 低于底座的 64.02，且 Backward Tracing 一栏 57.89 低于底座的 62.47。月级任务上最好也只有 17.62%（ReMA with GPT-5），VAM 的 17.11% 与之相差 0.51 个百分点，约合 266 题里的一到两道。全文没有任何组件消融，三个部件各自贡献多少无从判断。</p><p><strong>3 句版</strong>：免训练三件套——在线索引、层次记忆、智能体检索——把无界视频流变成可搜索可核验的记忆底座。OVO-Bench RT+BT 68.41、MM-Lifelong train@month 17.11%，存储降到原始流的 0.06%。相对同底座的净增益是 0.95 点，而 Backward Tracing 与 Forward Active Responding 两栏都低于底座。</p><p><strong>1 句版</strong>：把视觉记忆当成显式、可检查、可查询的底座是对的方向，但目前它相对强底座本身的增量还很薄。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>失败代价最大的一条是：<strong>架构层面的记忆机制能给强底座带来实质增量。</strong> 这是全文立论的落点，而表 <code>tab:ovobench</code> 对它的支持是有条件的，并且这个条件是作者自己选出来的。</p><p>先看整体口径。VAM 的 Overall 是 61.95，同底座 Gemini 3 Flash 是 64.02——加上记忆架构之后，OVO-Bench 的总分<strong>下降了 2.07 点</strong>。摘要与结论用的头条指标是 RT+BT 均值（68.41 对 67.46，+0.95），这个指标把 VAM 明显更差的 Forward Active Responding（49.01 对 57.15，−8.14）排除在外。作者对这个选择给了理由（RT 和 BT 才是最能反映记忆底座的两块），理由本身合理，但结果是：一个记忆系统在自己挑选的子指标上赢了 0.95 点，在完整指标上输了 2.07 点。</p><p>再看这 0.95 点的来源。RT 均值 +6.50 几乎全部来自单一子项：STU（Spatial Understanding）+23.20。六个 RT 子项的差值之和约为 39 点，STU 一项就占了 23.20，接近六成；而 OCR 一项其实是下降的（85.23 对 86.58）。更关键的是 BT——Backward Tracing 正是&quot;回溯早先证据&quot;这件事，也正是记忆架构的核心卖点——VAM 的 57.89 <strong>低于</strong>底座的 62.47，差 4.58 点。也就是说，在最应该体现记忆价值的那一栏上，加了记忆反而更差。</p><p>论文缺失的关键证据是<strong>组件消融</strong>。全文没有任何一处报告去掉在线索引、去掉层次记忆或去掉智能体检索之后的成绩。在总增益只有 0.95 点、且该增益集中于单一子项的情况下，三个部件各自是否有正贡献完全无法判断。此外月级结果的 17.11% 对 17.62% 只差 0.51 个百分点，在 266 题上约合 1.4 道题，论文也没有给置信区间或多次运行。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不必复现完整系统。一周内可做的最小验证聚焦在&quot;记忆架构相对同底座是否有净增益&quot;：</p><ol><li>取 OVO-Bench 的 Backward Tracing 三个子项（EPM / ASI / HLD，共若干百条），用同一个 MLLM 底座跑两条基线：端到端（按 OVO-Bench 协议均匀稀疏采样至上下文上限）与 VAM 的完整流程。</li><li>加两条被论文省略的对照：其一，<strong>只保留在线索引、跳过智能体检索</strong>，即把 VAM 索引出的 6,876 帧级别的稀疏帧集合直接一次性喂给底座；其二，<strong>只保留智能体检索、把索引换成均匀 0.5 fps</strong>，即在同样帧数预算下用最朴素的定速采样构造记忆池。</li><li>每条配置跑 3 个随机种子，报告均值与标准差。</li><li>判据：若配置一（无智能体检索）已经接近完整 VAM 的 BT 成绩，则多轮检索循环没有兑现价值；若配置二（均匀采样索引）接近完整 VAM，则 Otsu 自适应边界检测这一环可以被最平凡的定速采样替代。任一情形成立，论文关于&quot;三件套缺一不可&quot;的隐含主张就需要重写。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>第一重攻击针对指标选择。</strong> 最有力的攻击不需要任何新实验，只需要把表 <code>tab:ovobench</code> 的 Overall 一栏摆到摘要的位置：VAM 61.95 对 Gemini 3 Flash 64.02。一个自称能让长时程推理&quot;落在可恢复观测上&quot;的记忆框架，在同一基准的完整指标上低于它所包裹的那个模型 2.07 点。要让 RT+BT 这个口径站得住，论文需要额外论证 Fwd 一栏的退化是可接受的代价而非架构缺陷——作者给了定性解释（evidence-first 的控制器倾向于过早作答），但没有给出任何在 Fwd 上缓解这一倾向的对照实验（例如提高 continue-or-stop 的证据门槛后重测三栏）。缺这一格，读者无法判断 RT+BT 的 0.95 点与 Fwd 的 8.14 点是不是同一个设计选择的两面。</p><p><strong>第二重攻击针对增益的集中性。</strong> 构造一个&quot;去 STU&quot;的重算：把 RT 均值改成排除 Spatial Understanding 后的五项平均，重新计算 RT+BT。如果这个修正后的口径下 VAM 不再高于底座，那么本文关于&quot;系统性架构收益而非单任务假象&quot;的论断（正文原话是 &quot;suggesting a systematic architectural benefit rather than a single-task artefact&quot;）就被直接反驳。这个计算用表里现成的数字就能做，论文本可以自己给出而没有给。</p><p><strong>第三重攻击针对缺失的平凡基线。</strong> MM-Lifelong 的成本表已经给出了均匀 1 fps（380,304 帧）与 0.5 fps（190,152 帧）的帧数，却<strong>没有</strong>给出这两条定速采样在同一底座上的准确率。这意味着&quot;6,876 帧的自适应索引&quot;相对&quot;190,152 帧的定速采样&quot;到底是精度更高还是只是更省，论文没有回答。补上这一行的成本远低于跑整套智能体，而它决定了边界敏感索引的价值是&quot;更好&quot;还是仅仅&quot;更便宜&quot;。在 17.11% 这个绝对水平上（人类 82.5%），任何缺失的地板参照都会让读者高估方法的实际贡献。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：VAM 的索引决策是<strong>一次性且不可逆</strong>的。作者自己在 Limitations 里写明：&quot;A missed boundary or unretained subtle state change cannot be recovered downstream.&quot;换句话说，整个系统的性能上界在流经过的那一刻就被 Otsu 阈值锁死了，而这个阈值只看嵌入距离的分布，完全不知道未来会被问什么。这是一个把不可逆决策放在信息最少的时刻做的架构。</p><p><strong>换一个 framing</strong>：把&quot;保留哪一帧&quot;从流式时刻的一次性判断，改写成一个<strong>可延迟、可撤销的两级承诺</strong>。第一级在流经过时只做极便宜的可逆记录（例如保留高度压缩的缩略图与嵌入，成本远低于完整帧但足以支持后验重排）；第二级的&quot;晋升为完整证据&quot;发生在真实查询到达之后，或者在系统空闲时由一个后台过程根据历史查询分布回填。这样索引决策就从&quot;预测未来会问什么&quot;变成&quot;根据已经问过什么调整记忆&quot;，与压缩式路线的根本差别也就从&quot;存不存原始帧&quot;变成&quot;什么时候决定存&quot;。</p><p><strong>可借鉴的相邻领域工具</strong>：数据库领域的 LSM-tree 与分层 compaction（先廉价写入、后台按访问模式重整），以及缓存领域的 ghost cache / ARC（保留被淘汰项的元数据以便事后发现淘汰错了并自适应调整策略）。ghost cache 尤其贴切：它正是为了解决&quot;淘汰决策做早了、事后才知道错&quot;这一同构问题。</p><p><strong>第一个实验长什么样</strong>：先做纯测量，不改架构。在 MM-Lifelong 月级流上运行现有索引，同时<strong>额外保留一份完整的 0.5 fps 帧集合</strong>作为影子集。对 266 道题逐题检查：真值线索所在的帧是否落在 VAM 保留的 6,876 帧里。这会把失败拆成两类——&quot;证据根本没被索引下来&quot;（索引召回失败）与&quot;证据在库里但检索没找到&quot;（检索失败）。若第一类占多数，则上界确实被在线索引锁死，两级承诺的收益空间很大，值得投入实现；若第二类占多数，则应先改检索控制器而不是索引策略。这个测量只需要一次额外的存储，不需要重跑任何 MLLM 调用。</p>',59)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
